public class MainActivity extends AppCompatActivity {
    private static final int INK=0xff142a24,GREEN=0xff147653,PAPER=0xfff3f6ef,MUTED=0xff748177,LIME=0xffd0ed8c;
    private Repository repo;private Match match;private String page="Home",role="Organizer";private LinearLayout root,body;private TextToSpeech tts;private boolean audioReady,pa;
    private final Handler handler=new Handler(Looper.getMainLooper());private AlertDialog pending;
    @Override public void onCreate(Bundle state){super.onCreate(state);repo=new Repository(this);String id=getPreferences(0).getString("active","");for(Match m:repo.matches())if(m.id.equals(id))match=m;role=getPreferences(0).getString("role","Organizer");tts=new TextToSpeech(this,status->audioReady=status==TextToSpeech.SUCCESS);draw();}
    @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}handler.removeCallbacksAndMessages(null);repo.close();super.onDestroy();}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));v.setLineSpacing(dp(2),1);return v;}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private Button button(String s,boolean primary,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(12);b.setTextColor(primary?Color.WHITE:INK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(primary?GREEN:0xffe6eddc));b.setMinHeight(dp(48));b.setOnClickListener(v->guard(action));return b;}
    private void guard(Runnable r){try{r.run();}catch(Exception ex){message("Could not complete action",ex.getMessage()==null?ex.toString():ex.getMessage());}}
    private void message(String title,String s){new AlertDialog.Builder(this).setTitle(title).setMessage(s).setPositiveButton("OK",null).show();}
    private void gap(){View v=new View(this);body.addView(v,new LinearLayout.LayoutParams(1,dp(12)));}
    private void heading(String eyebrow,String h,String detail){body.addView(text(eyebrow.toUpperCase(Locale.ROOT),10,GREEN,true));TextView title=text(h,31,INK,true);title.setPadding(0,dp(5),0,dp(4));body.addView(title);body.addView(text(detail,13,MUTED,false));gap();}
    private LinearLayout card(String eyebrow,String title,String detail){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(17),dp(16),dp(17),dp(16));c.setBackground(bg(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);body.addView(c,p);c.addView(text(eyebrow.toUpperCase(Locale.ROOT),10,GREEN,true));TextView h=text(title,18,INK,true);h.setPadding(0,dp(4),0,dp(4));c.addView(h);if(!detail.isEmpty())c.addView(text(detail,13,MUTED,false));return c;}
    private void action(LinearLayout box,String label,Runnable r){Button b=button(label,true,r);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(49));p.topMargin=dp(9);box.addView(b,p);}
    private void grid(String[] labels,Consumer<String> callback){for(int i=0;i<labels.length;i+=3){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(labels.length,i+3);j++){String label=labels[j];Button b=button(label,label.equals("4")||label.equals("6"),()->callback.accept(label));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(50),1);p.setMargins(dp(2),dp(2),dp(2),dp(2));row.addView(b,p);}body.addView(row);}}
    private void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(PAPER);setContentView(root);ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets b=insets.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);return insets;});LinearLayout head=new LinearLayout(this);head.setPadding(dp(18),dp(8),dp(18),dp(4));head.setGravity(Gravity.CENTER_VERTICAL);head.addView(text("BOUNDARY /",17,GREEN,true),new LinearLayout.LayoutParams(0,dp(42),1));head.addView(button(role+" ▾",false,this::roles));root.addView(head);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(18),dp(10),dp(18),dp(24));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);for(String tab:new String[]{"Home","Score","Cups","Teams","Tools"}){Button b=button(tab,tab.equals(page),()->{page=tab;draw();});b.setTextSize(10);b.setPadding(0,0,0,0);nav.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(nav);switch(page){case "Score":score();break;case "Cups":cups();break;case "Teams":teams();break;case "Tools":tools();break;default:home();}}
    private void roles(){String[] rs={"Organizer","Manager","Scorer","Umpire","Captain","Player","Spectator"};new AlertDialog.Builder(this).setTitle("Workspace role").setItems(rs,(d,w)->{role=rs[w];getPreferences(0).edit().putString("role",role).apply();draw();}).show();}
    private boolean writable(){if(role.equals("Spectator")||role.equals("Player")){message("Read-only workspace","Choose the assigned organizer, scorer or umpire workspace to make match changes.");return false;}return true;}
    private void home(){heading("Local grounds. Big moments.","Your cricket,\nall together.","Tournaments, match-day decisions and every ball in between.");LinearLayout hero=card("Match-day desk","Ready for the first ball?","Set up teams and officials, choose your local rules, and score with or without internet.");action(hero,"Create a match",()->{if(writable())matchSetup(null,null);});for(Match m:repo.matches()){State s=m.state();LinearLayout c=card(m.result().equals("Live")?"IN PROGRESS":m.result(),m.name,s.runs+"/"+s.wickets+" · "+s.overs(m.rules)+" overs\n"+m.venue);action(c,"Open scorecard",()->open(m));}if(repo.matches().isEmpty())card("No sample records","Start with your teams","Add squads in Teams, then create a match or generate a tournament schedule.");}
    private void open(Match m){match=m;getPreferences(0).edit().putString("active",m.id).apply();page="Score";draw();}
    private void persist(){repo.save(match);getPreferences(0).edit().putString("active",match.id).apply();Publication.queue(this,repo,match);}
    private void score(){if(match==null){heading("Match centre","No match selected","Create a match from Home, or open a scheduled fixture.");return;}State s=match.state();heading("Match centre · Saved on this phone",match.current().battingTeam,match.name+" · "+match.venue);LinearLayout board=new LinearLayout(this);board.setOrientation(1);board.setPadding(dp(20),dp(20),dp(20),dp(20));board.setBackground(bg(INK,22));board.addView(text((s.closed?"INNINGS COMPLETE":"LIVE")+(s.freeHit?" · FREE HIT":""),10,LIME,true));board.addView(text(s.runs+" / "+s.wickets,48,Color.WHITE,true));board.addView(text(s.overs(match.rules)+" overs    CRR "+fmt(s.rate(match.rules)),13,0xffd3dfd5,false));if(s.target>0)board.addView(text("Target "+s.target+" · Need "+Math.max(0,s.target-s.runs)+" from "+Math.max(0,s.maxBalls-s.legal)+" balls",13,LIME,true));body.addView(board);gap();if(s.target>0){int p=Cricket.probability(s,match.rules);body.addView(text("Win estimate  "+p+"%",12,GREEN,true));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(p);body.addView(bar,new LinearLayout.LayoutParams(-1,dp(9)));gap();}StringBuilder bat=new StringBuilder();for(String name:new String[]{s.striker,s.nonStriker})if(!name.isEmpty()){Batting b=s.bat(name);bat.append(name).append(name.equals(s.striker)?" *":"").append("   ").append(b.runs).append(" (").append(b.balls).append(")\n");}String bowl=s.bowler.isEmpty()?"Select next bowler":s.bowler+"   "+s.bowl(s.bowler).wickets+"/"+s.bowl(s.bowler).runs;card("At the crease",bat.toString().trim(),"Bowling: "+bowl);if(!s.closed&&!role.equals("Spectator")&&!role.equals("Player")){if(s.bowler.isEmpty())action(body,"Choose bowler",this::bowler);grid(new String[]{"0","1","2","3","4","6"},v->ballDialog(Integer.parseInt(v),Extra.NONE));grid(new String[]{"Wide","No ball","Byes","Leg byes","Penalty","Wicket"},v->{switch(v){case "Wide":ballDialog(0,Extra.WIDE);break;case "No ball":ballDialog(0,Extra.NO_BALL);break;case "Byes":ballDialog(0,Extra.BYE);break;case "Leg byes":ballDialog(0,Extra.LEG_BYE);break;case "Penalty":ballDialog(0,Extra.PENALTY);break;default:wicket();}});grid(new String[]{"Undo","History","Batters","Retire hurt","Voice","Rain / time"},v->{switch(v){case "Undo":confirmReversal("Undo last delivery",()->{match.undo(1);persist();draw();});break;case "History":history();break;case "Batters":batters();break;case "Retire hurt":retire();break;case "Voice":voice();break;default:interrupt();}});}else if(s.closed&&match.innings.size()==1)action(body,"Start the chase",this::chase);if(match.innings.size()==2&&s.closed)card("Final result",match.result(),story());gap();grid(new String[]{"Scorecard","Share","Rules","History"},v->{if(v.equals("Scorecard"))scorecard();else if(v.equals("Share"))share();else if(v.equals("History"))history();else rules(match.rules,()->{persist();draw();});});gap();StringBuilder recent=new StringBuilder();for(int i=Math.max(0,s.commentary.size()-8);i<s.commentary.size();i++)recent.append(s.commentary.get(i)).append("\n\n");card("Ball by ball","Match commentary",recent.length()==0?"Waiting for the first delivery.":recent.toString());}
    private static String fmt(double n){return String.format(Locale.US,"%.2f",n);}
    private LinearLayout form(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(5),dp(18),dp(5));return box;}
    private EditText field(LinearLayout box,String label,String value,boolean number){box.addView(text(label,12,GREEN,true));EditText e=new EditText(this);e.setText(value);e.setSingleLine();if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);box.addView(e);return e;}
    private Spinner spinner(LinearLayout box,String label,String[] values){box.addView(text(label,12,GREEN,true));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));box.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));return s;}
    private CheckBox check(LinearLayout box,String label,boolean value){CheckBox c=new CheckBox(this);c.setText(label);c.setChecked(value);box.addView(c);return c;}
    private int num(EditText e){String x=e.getText().toString();return x.isEmpty()?0:Integer.parseInt(x);}
    private String val(EditText e){return e.getText().toString().trim();}
    private void dialog(String title,LinearLayout box,String positive,Runnable apply){ScrollView s=new ScrollView(this);s.addView(box);AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(s).setNegativeButton("Cancel",null).setPositiveButton(positive,null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(vv->{try{apply.run();d.dismiss();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}));d.show();}
    private void matchSetup(Tournament cup,Fixture fixture){LinearLayout box=form();List<Team> ts=repo.teams();if(ts.size()<2){message("Add teams first","Register at least two teams and two players per team in Teams.");return;}String[] names=ts.stream().map(t->t.name).toArray(String[]::new);Spinner a=spinner(box,"Batting first",names),b=spinner(box,"Bowling first",names);b.setSelection(1);if(fixture!=null){for(int i=0;i<names.length;i++){if(names[i].equals(fixture.a))a.setSelection(i);if(names[i].equals(fixture.b))b.setSelection(i);}}EditText venue=field(box,"Ground / turf","",false),scorer=field(box,"Scorer","",false),umpire=field(box,"Umpire","",false);dialog("Create match",box,"Set rules",()->{Team ta=ts.get(a.getSelectedItemPosition()),tb=ts.get(b.getSelectedItemPosition());if(ta.id.equals(tb.id))throw new IllegalArgumentException("Choose two different teams.");if(ta.players.size()<2||tb.players.size()<2)throw new IllegalArgumentException("Each team needs at least two named players.");Match m=new Match(ta.name,tb.name);m.venue=val(venue);m.scorer=val(scorer);m.umpire=val(umpire);m.rules.players=Math.max(2,Math.min(ta.players.size(),tb.players.size()));m.rules.bowlerOvers=m.rules.overs;m.innings.add(new Innings(ta.name,tb.name,ta.players.get(0),ta.players.get(1),0));if(cup!=null)m.tournament=cup.id;rules(m.rules,()->{repo.save(m);if(fixture!=null){fixture.matchId=m.id;repo.save(cup);}open(m);});});}
    private void rules(Rules r,Runnable saved){if(!writable())return;LinearLayout box=form();EditText bpo=field(box,"Balls per over (4, 5, 6, 8)",""+r.ballsPerOver,true),overs=field(box,"Overs",""+r.overs,true),players=field(box,"Players per side",""+r.players,true),wide=field(box,"Wide penalty",""+r.wide,true),nb=field(box,"No-ball penalty",""+r.noBall,true),limit=field(box,"Bowler over limit",""+r.bowlerOvers,true),pp=field(box,"Powerplay overs",""+r.powerplay,true);CheckBox last=check(box,"Last batter may bat solo",r.lastMan),legal=check(box,"Final-over wides / no-balls count as deliveries",r.finalOverExtrasLegal);dialog("Gully-to-Pro rules",box,"Save rules",()->{Rules next=new Rules();next.ballsPerOver=num(bpo);next.overs=num(overs);next.players=num(players);next.wide=num(wide);next.noBall=num(nb);next.bowlerOvers=num(limit);next.powerplay=num(pp);next.lastMan=last.isChecked();next.finalOverExtrasLegal=legal.isChecked();next.validate();r.ballsPerOver=next.ballsPerOver;r.overs=next.overs;r.players=next.players;r.wide=next.wide;r.noBall=next.noBall;r.bowlerOvers=next.bowlerOvers;r.powerplay=next.powerplay;r.lastMan=next.lastMan;r.finalOverExtrasLegal=next.finalOverExtrasLegal;saved.run();});}
    private void ballDialog(int runs,Extra extra){if(!writable())return;State state=match.state();if(state.closed){message("Innings complete","Start the chase or correct the delivery history.");return;}if(state.bowler.isEmpty()){bowler();return;}LinearLayout box=form();EditText bat=field(box,extra==Extra.NONE||extra==Extra.NO_BALL?"Bat runs":"Extras (excluding automatic penalty)",""+runs,true),physical=field(box,"Completed running runs (for strike rotation)",""+(runs%2),true),over=field(box,"Overthrow runs","0",true);CheckBox boundary=check(box,"Boundary (four or six)",runs==4||runs==6);Spinner zone=spinner(box,"Scoring zone",new String[]{"Unrecorded","Third man","Point","Cover","Straight off","Straight on","Midwicket","Square leg","Fine leg"});dialog(extra==Extra.NONE?"Record delivery":extra.name().replace('_',' '),box,"Save ball",()->{Event e=new Event();e.extra=extra;if(extra==Extra.NONE||extra==Extra.NO_BALL)e.bat=num(bat);else e.extras=num(bat);e.completed=num(physical);e.overthrow=num(over);e.boundary=boundary.isChecked();e.zone=zone.getSelectedItemPosition()-1;record(e);});}
    private void record(Event e){match.add(e);persist();if(pa&&audioReady){State s=match.state();if((e.boundary||e.dismissal!=Dismissal.NONE||s.legal%match.rules.ballsPerOver==0)&&!s.commentary.isEmpty())tts.speak(s.commentary.get(s.commentary.size()-1),TextToSpeech.QUEUE_ADD,null,e.id);}draw();}
    private String[] squad(String team){for(Team t:repo.teams())if(t.name.equals(team))return t.players.toArray(new String[0]);return new String[]{"Player"};}
    private String[] available(){State s=match.state();List<String> ps=new ArrayList<>();for(String p:squad(match.current().battingTeam)){Batting b=s.batting.get(p);if(!p.equals(s.striker)&&!p.equals(s.nonStriker)&&(b==null||!b.out))ps.add(p);}if(ps.isEmpty())ps.add("");return ps.toArray(new String[0]);}
    private void bowler(){if(!writable())return;LinearLayout box=form();Spinner p=spinner(box,"Bowler",squad(match.current().bowlingTeam));dialog("Select bowler",box,"Begin over",()->{String name=(String)p.getSelectedItem();State s=match.state();if(s.legal%match.rules.ballsPerOver!=0&&!s.bowler.isEmpty())throw new IllegalArgumentException("Finish the current over before changing the bowler.");if(s.bowl(name).balls>=match.rules.bowlerOvers*match.rules.ballsPerOver)throw new IllegalArgumentException("This bowler has reached the over limit.");Event e=new Event();e.kind=Kind.BOWLER;e.player=name;record(e);});}
    private void batters(){if(!writable())return;LinearLayout box=form();Spinner p=spinner(box,"Striker",squad(match.current().battingTeam)),q=spinner(box,"Non-striker",squad(match.current().battingTeam));if(q.getCount()>1)q.setSelection(1);dialog("Select batter ends",box,"Save ends",()->{if(p.getSelectedItem().equals(q.getSelectedItem()))throw new IllegalArgumentException("Choose different batters.");Event e=new Event();e.kind=Kind.BATTERS;e.player=(String)p.getSelectedItem();e.partner=(String)q.getSelectedItem();record(e);});}
    private void wicket(){if(!writable())return;LinearLayout box=form();Spinner type=spinner(box,"Dismissal",new String[]{"Bowled","Caught","LBW","Run out","Stumped","Hit wicket","Obstructing"}),incoming=spinner(box,"Incoming batter",available());CheckBox non=check(box,"Non-striker dismissed",false),cross=check(box,"Crossed on incomplete run",false);EditText completed=field(box,"Runs completed","0",true),fielder=field(box,"Fielder","",false);dialog("Record wicket",box,"Save wicket",()->{Event e=new Event();e.dismissal=Dismissal.values()[type.getSelectedItemPosition()+1];e.incoming=(String)incoming.getSelectedItem();e.nonStrikerOut=non.isChecked();e.crossed=cross.isChecked();e.bat=num(completed);e.completed=num(completed);e.fielder=val(fielder);record(e);});}
    private void retire(){if(!writable())return;LinearLayout box=form();Spinner p=spinner(box,"Retiring batter",new String[]{match.state().striker,match.state().nonStriker}),incoming=spinner(box,"Replacement",available());dialog("Retired hurt",box,"Substitute",()->{Event e=new Event();e.kind=Kind.RETIRE;e.player=(String)p.getSelectedItem();e.incoming=(String)incoming.getSelectedItem();record(e);});}
    private void chase(){if(!writable())return;LinearLayout box=form();String[] ps=squad(match.teamB);Spinner a=spinner(box,"Opening striker",ps),b=spinner(box,"Opening partner",ps);if(ps.length>1)b.setSelection(1);dialog("Start second innings",box,"Start chase",()->{if(a.getSelectedItem().equals(b.getSelectedItem()))throw new IllegalArgumentException("Choose different openers.");match.startChase((String)a.getSelectedItem(),(String)b.getSelectedItem());persist();draw();});}
    private void confirmReversal(String title,Runnable r){if(!writable())return;if(pending!=null)pending.dismiss();TextView msg=text("Applying in 3 seconds. Tap Cancel to keep the current decision.",15,INK,false);msg.setPadding(dp(22),dp(15),dp(22),dp(15));AlertDialog d=new AlertDialog.Builder(this).setTitle(title).setView(msg).setNegativeButton("Cancel",null).create();pending=d;d.show();if(audioReady)tts.speak(title+". Cancel within three seconds.",TextToSpeech.QUEUE_FLUSH,null,"reversal");handler.postDelayed(()->{if(d.isShowing()){d.dismiss();guard(r);}},3000);}
    private void history(){List<Event> events=match.current().events;String[] lines=new String[events.size()];for(int i=0;i<lines.length;i++)lines[i]=(i+1)+" · "+events.get(i).label();new AlertDialog.Builder(this).setTitle("Full delivery journal").setItems(lines,(d,index)->editEvent(index)).setNegativeButton("Close",null).show();}
    private void editEvent(int index){if(!writable())return;Event e=match.current().events.get(index);LinearLayout box=form();EditText runs=field(box,"Bat runs",""+e.bat,true),extras=field(box,"Additional extras",""+e.extras,true),completed=field(box,"Completed runs",""+e.completed,true),over=field(box,"Overthrows",""+e.overthrow,true);Spinner ex=spinner(box,"Extra type",Arrays.stream(Extra.values()).map(Enum::name).toArray(String[]::new));ex.setSelection(e.extra.ordinal());CheckBox out=check(box,"Wicket stands",e.dismissal!=Dismissal.NONE),reversed=check(box,"Decision reversed / remove entire event",e.reversed);dialog("Correct event "+(index+1),box,"Apply correction",()->{int bat=num(runs),extraRuns=num(extras),phys=num(completed),overRuns=num(over);confirmReversal("Recalculate match from event "+(index+1),()->{e.bat=bat;e.extras=extraRuns;e.completed=phys;e.overthrow=overRuns;e.extra=Extra.values()[ex.getSelectedItemPosition()];if(!out.isChecked())e.dismissal=Dismissal.NONE;e.reversed=reversed.isChecked();e.note="Corrected event "+(index+1);match.revision++;persist();draw();});});}
    private void interrupt(){if(!writable())return;LinearLayout box=form();State s=match.state();EditText remaining=field(box,"Revised remaining legal balls",""+Math.max(1,(s.maxBalls-s.legal)/2),true);box.addView(text("Local resource estimate; this is not the licensed official DLS method.",12,MUTED,false));dialog("Rain / turf time adjustment",box,"Calculate target",()->{int total=s.legal+num(remaining),target=Cricket.revisedTarget(s,total);message("Revised target",target==0?"First innings shortened to "+total+" legal balls.":"Revised target: "+target+" from "+num(remaining)+" remaining balls.");Event e=new Event();e.kind=Kind.INTERRUPTION;e.revisedBalls=total;e.revisedTarget=target;record(e);});}
    private void scorecard(){StringBuilder result=new StringBuilder();for(Innings in:match.innings){State s=in.state(match.rules);result.append(in.battingTeam).append("  ").append(s.runs).append('/').append(s.wickets).append(" (").append(s.overs(match.rules)).append(")\n\n");for(Map.Entry<String,Batting> entry:s.batting.entrySet()){Batting b=entry.getValue();result.append(entry.getKey()).append(b.out?"":" *").append("  ").append(b.runs).append(" (").append(b.balls).append(")  4s:").append(b.fours).append("  6s:").append(b.sixes).append("  SR ").append(fmt(b.balls==0?0:b.runs*100.0/b.balls)).append('\n');}result.append("\nBowling\n");for(Map.Entry<String,Bowling> entry:s.bowling.entrySet()){Bowling b=entry.getValue();result.append(entry.getKey()).append("  ").append(b.balls/match.rules.ballsPerOver).append('.').append(b.balls%match.rules.ballsPerOver).append("  ").append(b.wickets).append('/').append(b.runs).append(" Econ ").append(fmt(b.balls==0?0:b.runs*(double)match.rules.ballsPerOver/b.balls)).append('\n');}result.append("\nFall of wickets\n").append(String.join("\n",s.falls)).append("\n\n");}message("Full scorecard",result.toString());}
    private String story(){State s=match.state();String top="";int best=-1;for(Innings in:match.innings)for(Map.Entry<String,Batting> b:in.state(match.rules).batting.entrySet())if(b.getValue().runs>best){best=b.getValue().runs;top=b.getKey();}return match.result()+" at "+(match.venue.isEmpty()?"the ground":match.venue)+". "+top+" led the batting with "+Math.max(0,best)+" runs. "+s.wickets+" wickets fell in the chase, which ended on "+s.runs+" after "+s.overs(match.rules)+" overs.";}
    private void share(){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");State s=match.state();i.putExtra(Intent.EXTRA_TEXT,match.name+"\n"+match.current().battingTeam+" "+s.runs+"/"+s.wickets+" ("+s.overs(match.rules)+")\n"+match.result()+"\nhttps://boundary-cricket-tournament.vercel.app/?match="+match.id);startActivity(Intent.createChooser(i,"Share match"));}
    private void cups(){heading("Competition desk","Tournaments","League, group stage and knockout fixtures.");action(body,"Create tournament",this::newCup);gap();for(Tournament cup:repo.tournaments()){LinearLayout c=card(cup.format.name(),cup.name,cup.teams.size()+" registered teams · "+cup.fixtures.size()+" fixtures");action(c,"Registrations & schedule",()->cupDetail(cup));}}
    private void newCup(){if(!writable())return;LinearLayout box=form();EditText name=field(box,"Tournament name","",false);Spinner format=spinner(box,"Format",new String[]{"LEAGUE","KNOCKOUT","GROUPS"});dialog("New tournament",box,"Create",()->{if(val(name).isEmpty())throw new IllegalArgumentException("Enter a tournament name.");repo.save(new Tournament(val(name),Format.values()[format.getSelectedItemPosition()]));draw();});}
    private void cupDetail(Tournament cup){String[] options={"Register teams","Generate fixtures","Fixtures / start match","Points table"};new AlertDialog.Builder(this).setTitle(cup.name).setItems(options,(d,w)->guard(()->{if(w==0){if(!writable())return;List<Team> ts=repo.teams();String[] ns=ts.stream().map(t->t.name).toArray(String[]::new);boolean[] selected=new boolean[ns.length];for(int i=0;i<ns.length;i++)selected[i]=cup.teams.contains(ns[i]);new AlertDialog.Builder(this).setTitle("Registered teams").setMultiChoiceItems(ns,selected,(x,index,on)->selected[index]=on).setPositiveButton("Save",(x,y)->{if(!cup.fixtures.isEmpty()){message("Schedule already created","Team registrations are locked after generating fixtures.");return;}cup.teams.clear();for(int i=0;i<ns.length;i++)if(selected[i])cup.teams.add(ns[i]);repo.save(cup);draw();}).show();}else if(w==1){if(!writable())return;cup.generate();repo.save(cup);draw();}else if(w==2){String[] fixtures=cup.fixtures.stream().map(f->f.round+" · "+f.a+" v "+f.b).toArray(String[]::new);new AlertDialog.Builder(this).setTitle("Fixtures").setItems(fixtures,(x,i)->{Fixture f=cup.fixtures.get(i);for(Match m:repo.matches())if(m.id.equals(f.matchId)){open(m);return;}if(!writable())return;if(f.a.equals("BYE")||f.b.equals("BYE")){message("Bye","This team advances without a match.");return;}matchSetup(cup,f);}).show();}else{StringBuilder table=new StringBuilder("Team · P · W · L · Pts · NRR\n\n");for(Cricket.Row r:Cricket.standings(cup,repo.matches()))table.append(r.team).append(" · ").append(r.played).append(" · ").append(r.won).append(" · ").append(r.lost).append(" · ").append(r.points).append(" · ").append(fmt(r.nrr(6))).append('\n');message("Points table",table.toString());}})).show();}
    private void teams(){heading("Squads & player careers","Teams","Your teams, players and recorded career figures.");action(body,"Register a team",()->{if(!writable())return;LinearLayout box=form();EditText name=field(box,"Team name","",false),names=field(box,"Player names, comma separated","",false);names.setSingleLine(false);dialog("Register team",box,"Save team",()->{if(val(name).isEmpty())throw new IllegalArgumentException("Enter a team name.");for(Team t:repo.teams())if(t.name.equalsIgnoreCase(val(name)))throw new IllegalArgumentException("That team already exists.");Team t=new Team(val(name));for(String p:val(names).split(","))if(!p.trim().isEmpty()&&!t.players.contains(p.trim()))t.players.add(p.trim());repo.save(t);draw();});});gap();for(Team t:repo.teams()){LinearLayout c=card("SQUAD · "+t.players.size()+" players",t.name,String.join(" · ",t.players));action(c,"Players & career statistics",()->players(t));}}
    private void players(Team t){List<String> opts=new ArrayList<>(t.players);opts.add("+ Add player");new AlertDialog.Builder(this).setTitle(t.name).setItems(opts.toArray(new String[0]),(d,w)->{if(w==t.players.size()){if(!writable())return;LinearLayout box=form();EditText name=field(box,"Player name","",false);dialog("Add player",box,"Add",()->{if(val(name).isEmpty()||t.players.contains(val(name)))throw new IllegalArgumentException("Enter a new player name.");t.players.add(val(name));repo.save(t);draw();});}else career(t.players.get(w));}).show();}
    private void career(String player){int runs=0,balls=0,wickets=0,conceded=0,bowled=0;int[] zones=new int[8];Map<String,Integer> dismissals=new LinkedHashMap<>();for(Match m:repo.matches())for(Innings in:m.innings){State s=in.state(m.rules);Batting bt=s.batting.get(player);if(bt!=null){runs+=bt.runs;balls+=bt.balls;for(int z=0;z<8;z++)zones[z]+=bt.zones[z];if(bt.out)dismissals.put(bt.dismissal,dismissals.getOrDefault(bt.dismissal,0)+1);}Bowling bw=s.bowling.get(player);if(bw!=null){wickets+=bw.wickets;conceded+=bw.runs;bowled+=bw.balls;}}message(player+" · Career",runs+" runs · "+balls+" balls · SR "+fmt(balls==0?0:runs*100.0/balls)+"\n"+wickets+" wickets · "+conceded+" conceded · "+bowled+" deliveries\n\nScoring zones (third man clockwise)\n"+Arrays.toString(zones)+"\n\nDismissals\n"+dismissals);}
    private void tools(){heading("Intelligence & ground tools","Match-day toolkit","Voice, camera, imports, announcements and spectator publishing.");LinearLayout v=card("Hands-free scorer","Voice commands","Speak scoring and correction commands. Each recognized command is confirmed before execution.");action(v,"Speak a command",this::voice);LinearLayout a=card("Stadium PA","Ground announcements",pa?"Announcements enabled":"Connect a Bluetooth speaker using Android audio settings, then enable match announcements.");action(a,pa?"Disable announcer":"Enable announcer",()->{pa=!pa;draw();});LinearLayout f=card("Captain’s co-pilot","Field placement radar",tactic());FieldView field=new FieldView(this);f.addView(field,new LinearLayout.LayoutParams(-1,dp(300)));f.addView(text("Drag the nine fielders to adjust your plan.",12,MUTED,false));LinearLayout scan=card("Paper scorebook","Import & review","Choose a scoresheet image, extract text, and review the result before adding a past match.");action(scan,"Scan scorebook",()->startActivity(new Intent(this,ScannerActivity.class)));LinearLayout cam=card("Square-leg review","Stump cam","Record short rolling segments and retain the latest action for slow playback.");action(cam,"Open stump cam",()->startActivity(new Intent(this,StumpCamActivity.class)));LinearLayout sync=card("Public spectator scoreboard","Publish match",Publication.status(this,repo));action(sync,"Publish / sync saved matches",()->{Publication.sync(this,repo);Toast.makeText(this,"Sync requested",Toast.LENGTH_SHORT).show();});action(sync,"Open spectator website",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://boundary-cricket-tournament.vercel.app/"))));}
    private String tactic(){if(match==null)return "Record batter scoring zones to get a fielding suggestion.";Batting b=match.state().bat(match.state().striker);int best=0;for(int i=1;i<8;i++)if(b.zones[i]>b.zones[best])best=i;if(Arrays.stream(b.zones).sum()==0)return "No scoring-zone history yet. Start with a balanced field and attack the stumps.";String[] zones={"third man","point","cover","straight off","straight on","midwicket","square leg","fine leg"};return "Protect "+zones[best]+", the batter’s strongest recorded zone, and bowl away from that scoring arc.";}
    private void voice(){if(match==null){message("Select a match","Open a match before using voice scoring.");return;}if(!writable())return;if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},11);return;}try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_PROMPT,"Scorer: four, wide, undo last two balls, change last ball to six");startActivityForResult(i,12);}catch(ActivityNotFoundException e){message("Voice recognition unavailable","Install or enable an Android speech recognition service.");}}
    @Override public void onRequestPermissionsResult(int req,String[] ps,int[] results){super.onRequestPermissionsResult(req,ps,results);if(req==11&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)voice();}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==12&&result==RESULT_OK&&data!=null){ArrayList<String> results=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(results==null||results.isEmpty())return;String heard=results.get(0);new AlertDialog.Builder(this).setTitle("Confirm official’s command").setMessage(heard+"\n\nCheck the recognized words before applying.").setNegativeButton("Ignore",null).setPositiveButton("Apply",(d,w)->guard(()->command(heard))).show();}}
    private int spokenNumber(String s){String[] words={"zero","one","two","three","four","five","six"};for(int i=6;i>=0;i--)if(s.matches(".*\\b("+words[i]+"|"+i+")\\b.*"))return i;return 0;}
    private void command(String heard){String s=heard.toLowerCase(Locale.ROOT);if(s.contains("undo")){int n=spokenNumber(s);confirmReversal("Undo "+Math.max(1,n)+" deliveries",()->{match.undo(Math.max(1,n));persist();draw();});return;}if(s.contains("not out")){List<Event> es=match.current().events;for(int i=es.size()-1;i>=0;i--){Event e=es.get(i);if(!e.reversed&&e.dismissal!=Dismissal.NONE){confirmReversal("Reverse wicket",()->{e.dismissal=Dismissal.NONE;e.incoming="";persist();draw();});return;}}throw new IllegalArgumentException("No wicket found.");}if(s.contains("change")||s.contains("correction")){List<Event> es=match.current().events;for(int i=es.size()-1;i>=0;i--)if(es.get(i).kind==Kind.BALL&&!es.get(i).reversed){editEvent(i);return;}}if(s.contains("run out")||s.contains("wicket")||s.matches(".*\\bout\\b.*")){wicket();return;}Extra extra=s.contains("wide")?Extra.WIDE:s.contains("no ball")?Extra.NO_BALL:s.contains("leg bye")?Extra.LEG_BYE:s.contains("bye")?Extra.BYE:Extra.NONE;ballDialog(spokenNumber(s),extra);}
}
